#include <stdio.h>

static unsigned long long power_mod(unsigned long long a, unsigned long long b, unsigned long long m) {
    if (m == 1) return 0;
    if (b == 0) return 1 % m;
    unsigned long long half = power_mod(a, b / 2, m);
    unsigned long long half_sq = (half * half) % m;
    if (b & 1) {
        return (half_sq * (a % m)) % m;
    }
    return half_sq;
}

int main(void) {
    int t;
    if (scanf("%d", &t) != 1) return 0;
    while (t--) {
        unsigned long long a, b, m;
        scanf("%llu %llu %llu", &a, &b, &m);
        printf("%llu\n", power_mod(a, b, m));
    }
    return 0;
}

