static long long target;

static bool solve(int idx, long long current_sum, int count) {
    if (idx == n) {
        return (count > 0 && current_sum == target);
    }
    // Include arr[idx]
    if (solve(idx + 1, current_sum + arr[idx], count + 1)) return true;
    // Exclude arr[idx]
    if (solve(idx + 1, current_sum, count)) return true;
    return false;
}

