#include <stdio.h>

static void solve_queens(int row, int cols, int d1, int d2, int mask, int *count) {
    if (cols == mask) {
        (*count)++;
        return;
    }
    int available = mask & ~(cols | d1 | d2);
    while (available) {
        int p = available & -available;
        available -= p;
        solve_queens(row + 1, cols | p, (d1 | p) << 1, (d2 | p) >> 1, mask, count);
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int mask = (1 << n) - 1;
    int count = 0;
    solve_queens(0, 0, 0, 0, mask, &count);

    printf("%d\n", count);
    return 0;
}

