#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

static char str[16];
static int len;
static bool used[16];
static char current[16];

static char results[45000][16];
static int total_count = 0;

static int cmp_char(const void *a, const void *b) {
    return (*(const char *)a - *(const char *)b);
}

static void permute(int depth) {
    if (depth == len) {
        current[depth] = '\0';
        strcpy(results[total_count++], current);
        return;
    }
    for (int i = 0; i < len; i++) {
        if (used[i]) continue;
        if (i > 0 && str[i] == str[i - 1] && !used[i - 1]) continue;

        used[i] = true;
        current[depth] = str[i];
        permute(depth + 1);
        used[i] = false;
    }
}

int main(void) {
    if (scanf("%15s", str) != 1) return 0;
    len = strlen(str);
    qsort(str, len, sizeof(char), cmp_char);

    permute(0);

    printf("%d\n", total_count);
    for (int i = 0; i < total_count; i++) {
        printf("%s\n", results[i]);
    }
    return 0;
}

