#include <stdio.h>

static int arr[100005];

static int recursive_binary_search(int a[], int low, int high, int target, int *comparisons) {
    if (low > high) return -1;
    int mid = low + (high - low) / 2;
    (*comparisons)++;
    if (a[mid] == target) return mid;
    if (target < a[mid]) {
        return recursive_binary_search(a, low, mid - 1, target, comparisons);
    } else {
        return recursive_binary_search(a, mid + 1, high, target, comparisons);
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }
    int q;
    if (scanf("%d", &q) != 1) return 0;
    while (q--) {
        int target;
        scanf("%d", &target);
        int comps = 0;
        int idx = recursive_binary_search(arr, 0, n - 1, target, &comps);
        if (idx != -1) {
            printf("Found at index %d with %d comparisons\n", idx, comps);
        } else {
            printf("Not found with %d comparisons\n", comps);
        }
    }
    return 0;
}

