#include <stdio.h>

static int arr[100005];
static int temp[100005];

static long long merge(int a[], int tmp[], int left, int mid, int right) {
    int i = left;
    int j = mid + 1;
    int k = left;
    long long inv_count = 0;

    while (i <= mid && j <= right) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            tmp[k++] = a[j++];
            inv_count += (mid - i + 1);
        }
    }
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= right) tmp[k++] = a[j++];
    for (i = left; i <= right; i++) a[i] = tmp[i];

    return inv_count;
}

static long long merge_sort(int a[], int tmp[], int left, int right) {
    long long inv_count = 0;
    if (left < right) {
        int mid = left + (right - left) / 2;
        inv_count += merge_sort(a, tmp, left, mid);
        inv_count += merge_sort(a, tmp, mid + 1, right);
        inv_count += merge(a, tmp, left, mid, right);
    }
    return inv_count;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    long long invs = merge_sort(arr, temp, 0, n - 1);

    for (int i = 0; i < n; i++) {
        if (i > 0) printf(" ");
        printf("%d", arr[i]);
    }
    printf("\nInversions: %lld\n", invs);
    return 0;
}

