#include <stdio.h>
#include <string.h>

static long long super_digit(long long n) {
    if (n < 10) return n;
    long long sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return super_digit(sum);
}

int main(void) {
    char s[100005];
    long long k;
    if (scanf("%100004s %lld", s, &k) != 2) return 0;

    long long initial_sum = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        initial_sum += (s[i] - '0');
    }
    initial_sum *= k;

    printf("%lld\n", super_digit(initial_sum));
    return 0;
}

