#include <stdio.h>
#include <stdbool.h>

static int R, C;
static char grid[20][20];
static bool visited[20][20];
static char path[500];
static int path_len = 0;
static bool in_path[20][20];

static const int dr[] = {-1, 0, 1, 0};
static const int dc[] = {0, 1, 0, -1};
static const char dir_char[] = {'U', 'R', 'D', 'L'};

static bool dfs(int r, int c) {
    if (grid[r][c] == 'E') return true;

    visited[r][c] = true;
    for (int i = 0; i < 4; i++) {
        int nr = r + dr[i];
        int nc = c + dc[i];
        if (nr >= 0 && nr < R && nc >= 0 && nc < C && !visited[nr][nc] && grid[nr][nc] != '#') {
            path[path_len++] = dir_char[i];
            if (grid[nr][nc] != 'E') in_path[nr][nc] = true;
            if (dfs(nr, nc)) return true;
            if (grid[nr][nc] != 'E') in_path[nr][nc] = false;
            path_len--;
        }
    }
    return false;
}

int main(void) {
    if (scanf("%d %d", &R, &C) != 2) return 0;
    int sr = -1, sc = -1;
    for (int r = 0; r < R; r++) {
        scanf("%19s", grid[r]);
        for (int c = 0; c < C; c++) {
            if (grid[r][c] == 'S') {
                sr = r; sc = c;
            }
        }
    }

    if (dfs(sr, sc)) {
        path[path_len] = '\0';
        printf("PATH FOUND\n");
        printf("Path: %s\n", path);
        printf("Steps: %d\n", path_len);
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (in_path[r][c]) putchar('*');
                else putchar(grid[r][c]);
            }
            putchar('\n');
        }
    } else {
        printf("NO PATH\n");
    }
    return 0;
}

