#include <stdio.h>
#include <string.h>

#define MAXN 10005

static int memo_F[MAXN];
static int memo_M[MAXN];

static int male(int n);

static int female(int n) {
    if (n == 0) return 1;
    if (memo_F[n] != -1) return memo_F[n];
    memo_F[n] = n - male(female(n - 1));
    return memo_F[n];
}

static int male(int n) {
    if (n == 0) return 0;
    if (memo_M[n] != -1) return memo_M[n];
    memo_M[n] = n - female(male(n - 1));
    return memo_M[n];
}

int main(void) {
    memset(memo_F, -1, sizeof(memo_F));
    memset(memo_M, -1, sizeof(memo_M));

    int t;
    if (scanf("%d", &t) != 1) return 0;
    while (t--) {
        int n;
        scanf("%d", &n);
        printf("F(%d) = %d, M(%d) = %d\n", n, female(n), n, male(n));
    }
    return 0;
}
